sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        // Clear the target email field
        g_form.setValue('employee_email', '');
        return;
    }

    g_form.getReference('employeename', populateEmail);

    function populateEmail(userRecord) {
        // Check if a valid record was returned (userRecord) and if it has an email property
        if (userRecord && userRecord.email) {
            // Set the value of the target email field ('employee_email')
            g_form.setValue('employee_email', userRecord.email);
        } else {
            // Clear the email field if the user record is invalid or lacks an email
            g_form.setValue('employee_email', '');
        }
    }
}
